mapper.select:
SELECT T1.ENTRUST_ID entrustId, T1.ENTRUST_STATUS entrustStatus, T1.PORTFOLIO_ID portfolioId,
T1.INV_MANAGER_ID invManagerId,
T2.PORTFOLIO_NAME portfolioName,
T4.ASSET_TYPE1 assetType1, T4.ASSET_TYPE_10 assetType10, T4.ASSET_TYPE_11 assetType11,
T1.FINPROD_ID finprodId, T3.FINPROD_MARKET_ID finprodMarketId, T3.FINPROD_NAME finprodName, T1.PS ps, T1.ENTRUST_AMT entrustAmt, T1.ENTRUST_NUM entrustNum, T1.CCY ccy, T1.VDATE vdate, T1.MDATE mdate, IFNULL(T5.FINISH_AMT,0) finishAmt, round(IFNULL(T5.FINISH_AMT,0)/IFNULL(T1.ENTRUST_AMT,T1.ENTRUST_NUM),4)*100 transactioncom, T1.REMARK remark FROM ETR_ENTRUST T1 LEFT JOIN PTL_PORTFOLIO T2 ON T1.PORTFOLIO_ID = T2.PORTFOLIO_ID INNER JOIN FIN_PRODUCT T3 ON T1.FINPROD_ID = T3.FINPROD_ID INNER JOIN ETR_ENTRUST_ADD T4 ON T4.ENTRUST_ID = T1.ENTRUST_ID LEFT JOIN ( SELECT ENTRUST_ID, SUM(IFNULL(FINISH_AMT,0)) FINISH_AMT FROM ETR_FINISH_STATUS GROUP BY ENTRUST_ID) T5 ON T1.ENTRUST_ID = T5.ENTRUST_ID INNER JOIN PTL_PORTFOLIO_AUTHORITY T6 ON T2.PORTFOLIO_ID = T6.PORTFOLIO_ID
AND T6.USER_ID = #{userId}
AND (T2.PORTFOLIO_ID IN
null) OR T2.PORTFOLIO_ID IN (
#{prot}
or T2.PARENT_PORTFOLIO_ID IN
null) OR T2.PARENT_PORTFOLIO_ID IN (
#{prot}
)
AND T4.ASSET_TYPE1 in
#{item}
AND T4.ASSET_TYPE_10 in
#{item}
AND T4.ASSET_TYPE_11 in
#{item}
AND T1.CCY = #{ccy}
AND (T3.FINPROD_MARKET_ID like concat('%',concat(#{finprodId},'%')) OR T3.FINPROD_NAME like concat('%',concat(#{finprodId},'%')))
AND T1.PS=#{ps}
AND T1.ENTRUST_STATUS = #{entrustStatus}
AND T1.VDATE >=STR_TO_DATE(#{startDate},'%Y-%m-%d')
AND T1.MDATE <=STR_TO_DATE(#{endDate},'%Y-%m-%d')
AND T1.FINPROD_TYPE2 = #{FINPROD_TYPE2} AND T3.PROFIT_TYPE = #{PROFIT_TYPE}
order by T1.ENTRUST_ID DESC
